            /**
             * Position as shown, e.g. "T3".
             */
            displayPosition: string | null;
            /**
             * ELIMINATED covers a missed cut; golf surfaces show it as "Cut".
             */
            status: 'ACTIVE' | 'IN_PROGRESS' | 'COMPLETE' | 'WITHDRAWN' | 'ELIMINATED';
            /**
             * ISO 8601 datetime string.
             */
